import pytest
from candidate import hex_key

def test_hex_key_empty_string_returns_zero():
    assert hex_key("") == 0

def test_hex_key_no_prime_digits_returns_zero():
    assert hex_key("02468ACEF") == 0

def test_hex_key_all_prime_digits():
    assert hex_key("2357BD") == 6

def test_hex_key_mixed_example_ab():
    assert hex_key("AB") == 1

def test_hex_key_mixed_example_1077E():
    assert hex_key("1077E") == 2

def test_hex_key_complex_example():
    assert hex_key("ABED1A33") == 4

def test_hex_key_long_example():
    assert hex_key("123456789ABCDEF0") == 6

def test_hex_key_repeated_and_mixed():
    assert hex_key("222333555777BBBBDD") == 17

def test_hex_key_none_input_raises_type_error():
    with pytest.raises(TypeError):
        hex_key(None)

def test_hex_key_int_input_raises_type_error():
    with pytest.raises(TypeError):
        hex_key(123)

def test_hex_key_bytes_input_returns_zero():
    assert hex_key(b'AB') == 0

def test_hex_key_list_input_counts_correct():
    assert hex_key(['2', '3', '5', 'G']) == 3

def test_hex_key_function_returns_int():
    assert isinstance(hex_key("2B"), int)

def test_hex_key_input_unchanged():
    s = "2B5D"
    hex_key(s)
    assert s == "2B5D"

def test_hex_key_lowercase_returns_zero():
    assert hex_key("ab") == 0

def test_hex_key_large_prime_string():
    large = "2" * 1000 + "B" * 1000
    assert hex_key(large) == 2000

def test_hex_key_string_with_non_hex_characters():
    # The function will treat non-hex characters as non-prime
    assert hex_key("2G3H5I") == 3

def test_hex_key_string_with_spaces():
    assert hex_key("2 3 5") == 3

def test_hex_key_string_with_newlines():
    assert hex_key("2\n3\n5") == 3

def test_hex_key_string_with_non_ascii():
    # Non-ASCII characters are treated as non-prime
    assert hex_key("2\u00A9") == 1

def test_hex_key_string_with_mixed_case_and_valid_digits():
    assert hex_key("2a3B5c") == 4
